import { paymentMethods, type PaymentMethod } from '../../icons/payment-names';
import './PaymentIcon.css';

/* The Figma "Payment method icon" set (src/icons/payment, generated by `npm run icons`). */
const files = import.meta.glob<string>('../../icons/payment/*.svg', { eager: true, query: '?no-inline', import: 'default' });

export { paymentMethods, type PaymentMethod };

/** Width for each height: the icons are 34 × 24 cards, the guidelines measure 45 × 32 and 28 × 20. */
const WIDTH = { 32: 45, 24: 34, 20: 28 } as const;

export type PaymentIconProps = {
  /** Figma Payment method in lower case with hyphens: "Shop Pay" → `shop-pay`; `empty` is a blank card */
  method: PaymentMethod;
  /** Height in px: 32, 24 or 20. The width follows the card proportions (45, 34, 28). */
  size?: 20 | 24 | 32;
  /** Accessible name, such as "Visa". Leave it out when the method is written next to the icon. */
  label?: string;
  className?: string;
};

/** A payment method or provider logo on a small card (Figma "Payment method icon"). */
export function PaymentIcon({ method, size = 24, label, className = '' }: PaymentIconProps) {
  return (
    <img
      className={`grg-payment-icon ${className}`}
      src={files[`../../icons/payment/${method}.svg`]}
      width={WIDTH[size]}
      height={size}
      alt={label ?? ''}
      loading="lazy"
      decoding="async"
    />
  );
}
